      &&e.left.computed&&e.left.object.type==='ThisExpression'&&e.left.property.type==='Identifier'
      &&e.left.property.name===a&&e.right.type==='Identifier'&&e.right.name===b)
    return {shape:'dynamic_instance_assignment',code:text};
